import sys
from math import gcd

def min_operations_to_one(n, a):
    if 1 in a:
        return n - a.count(1)

    total_gcd = a[0]
    for num in a:
        total_gcd = gcd(total_gcd, num)

    if total_gcd != 1:
        return -1

    operations = 0
    ones_count = 0

    for num in a:
        if num == 1:
            ones_count += 1
        else:
            operations += 1
            while num > 1:
                num = gcd(num, total_gcd)
                operations += 1

    return operations + n - ones_count - 1

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    a = list(map(int, data[1:]))

    result = min_operations_to_one(n, a)
    print(result)

if __name__ == "__main__":
    main()
